package net.civeira.phylax.features.access.user.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class EmailVerifiedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property email verified of user ")
  void test_email_verified_v_o_builder() {
    Assertions.assertFalse(EmailVerifiedVO.nullValue().isEmailVerified(),
        "A empty vo should have a null value");
    Assertions.assertFalse(EmailVerifiedVO.tryFrom(null).isEmailVerified(),
        "With a null value, no present result");
    Assertions.assertEquals(true, EmailVerifiedVO.from(true).isEmailVerified());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> EmailVerifiedVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", EmailVerifiedVO.from(true).toString());
  }
}
